const ENVIRONMENTS: [string,string][] = [['development','开发'],['test','测试'],['staging','预发布'],['production','生产']];
const EMPTY = (): Record<V1Domain,V1Collection> => ({inbox:{items:[],nextCursor:null,snapshotVersion:0},research:{items:[],nextCursor:null,snapshotVersion:0},projects:{items:[],nextCursor:null,snapshotVersion:0},tasks:{items:[],nextCursor:null,snapshotVersion:0},experiences:{items:[],nextCursor:null,snapshotVersion:0}});
const str=(value:unknown) => typeof value==='string'?value:'';
const arr=(value:unknown):Record<string,unknown>[] => Array.isArray(value)?value.filter(x=>x&&typeof x==='object'):[];
const lines=(value:unknown) => str(value).split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
const name=(value:V1Record) => value.title||value.name||'未命名记录';
const scopeName=(scope:unknown) => SCOPES.find(x=>x[0]===scope)?.[1]||str(scope);
const date=(value:unknown) => value&&Number.isFinite(Date.parse(String(value)))?new Date(String(value)).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'未记录时间';
function Icon({type,small=false}:{type:string;small?:boolean}) {
  const paths:Record<string,ReactNode>={inbox:<><path d="M4 3h16v18H4zM4 14h5l1 3h4l1-3h5M8 7h8M8 10h5"/></>,research:<><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M7 10h6M10 7v6"/></>,projects:<><path d="M3 7V4h7l2 3h9v13H3zM7 11h10M7 15h7"/></>,tasks:<><rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 9 2 2 5-5M8 15h8M8 18h5"/></>,experiences:<><path d="M4 3h12l4 4v14H4zM16 3v5h4M8 12h8M8 16h6"/></>,arrow:<path d="M5 12h14m-6-6 6 6-6 6"/>,refresh:<><path d="M20 8V3l-4 1M4 16v5l4-1M20 8a8 8 0 0 0-14-3M4 16a8 8 0 0 0 14 3"/></>,shield:<><path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/></>,plus:<path d="M12 5v14M5 12h14"/>,logout:<><path d="M9 3H3v18h6M9 12h12m-5-5 5 5-5 5"/></>,check:<path d="m5 12 4 4L19 6"/>,search:<><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></>,link:<><path d="m9 15 6-6M7 13l-2 2a4 4 0 0 0 6 6l3-3M10 6l3-3a4 4 0 0 1 6 6l-2 2"/></>};
  return <svg width={small?16:21} height={small?16:21} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[type]||paths.tasks}</svg>;
}
function Badge({children,tone=''}:{children:ReactNode;tone?:string}){return <span className={`v1-badge ${tone}`}>{children}</span>}
function Block({label,children}:{label:string;children:ReactNode}){return <section className="v1-block"><h3>{label}</h3>{children}</section>}
function Text({value}:{value:unknown}) {return str(value)?<p className="v1-prose">{str(value)}</p>:<span className="v1-muted">尚未填写</span>}
function Links(){return <nav className="v1-links"><a href="?mode=platform">完整平台 <Icon type="arrow" small/></a><a href="?mode=demo">交互演示 <Icon type="arrow" small/></a><a href="?mode=live">真实控制台 <Icon type="arrow" small/></a></nav>}
function Modal({title,subtitle,onClose,children}:{title:string;subtitle?:string;onClose:()=>void;children:ReactNode}) {
  const ref=useRef<HTMLDivElement>(null);const close=useRef(onClose);close.current=onClose;
  useEffect(()=>{const old=document.activeElement as HTMLElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.querySelector<HTMLElement>('input,textarea,select')?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape')close.current();if(e.key==='Tab'){const all=Array.from(ref.current?.querySelectorAll<HTMLElement>('button,input,select,textarea,a[href]')||[]).filter(n=>!n.hasAttribute('disabled'));if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0]?.focus()}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',key);old?.focus()};},[]);
  return <div className="v1-modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="v1-modal" ref={ref} role="dialog" aria-modal="true" aria-label={title}><header><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="v1-icon" aria-label="关闭" onClick={onClose}>×</button></header>{children}</div></div>;
}

type Option=[string,string];
interface Field {key:string;label:string;type?:'text'|'textarea'|'number'|'select'|'lines'|'check'|'multi'|'copies'|'datetime';required?:boolean;options?:Option[];value?:unknown;hint?:string;min?:number;max?:number}
interface Spec {title:string;note:string;submit:string;fields:Field[];make:(values:Record<string,unknown>)=>Record<string,unknown>}
type Action={domain:V1Domain;command:string;target?:V1Record};
const COMMAND_LABELS:Record<string,string>={'inbox.annotate':'补充批注','inbox.merge':'合并记录','inbox.route':'整理归档','inbox.ignore':'忽略记录','inbox.capture-policy':'采集授权','research.discuss':'补充讨论','research.start':'启动后台研究','research.pause':'暂停研究','research.evidence':'登记证据','research.option':'添加方案','research.decide':'作出决策','research.convert':'转为项目','projects.copies':'工作副本','projects.milestone':'里程碑确认','projects.plan':'生成任务计划','projects.archive':'归档项目','tasks.report':'录入外部进度','tasks.pause':'登记暂停','tasks.cancel':'取消任务','tasks.accept':'独立验收','tasks.package':'打包交付','tasks.start':'启动执行器','tasks.resume':'继续执行器','tasks.retry':'执行器重试','experiences.verify':'验证经验','experiences.merge':'合并经验','experiences.skill-publish':'发布技能','experiences.version':'修订版本','experiences.reuse':'固定版本复用','experiences.deprecate':'停用经验'};
const field=(key:string,label:string,type:Field['type']='text',value:unknown='',required=true,hint?:string):Field=>({key,label,type,value,required,hint});
const select=(key:string,label:string,options:Option[],value?:unknown,required=true):Field=>({key,label,type:'select',options,value:value??options[0]?.[0]??'',required});
function specFor(action:Action,collections:Record<V1Domain,V1Collection>,devices:Device[],activeScope?:V1Scope):Spec {
  const {domain,command,target:t}=action;const id=t?.id;const a=`${domain}.${command}`;
  const desiredScope=t?.scope||activeScope;
  const same=(d:V1Domain)=>collections[d].items.filter(x=>x.id!==id&&(!desiredScope||x.scope===desiredScope)).map(x=>[x.id,name(x)] as Option);
  const machineOptions=devices.map(x=>[x.id,`${x.name} · ${x.status==='online'?'本机在线':'状态未知'}`] as Option);
  const projectOptions=collections.projects.items.filter(x=>!['archived','delivered'].includes(x.status)&&(!desiredScope||x.scope===desiredScope)).map(x=>[x.id,name(x)] as Option);
  const machine=select('machineId','开发设备',machineOptions,'local');
  const budget={...field('budget','预算上限 · 元','number',50),min:1,max:10000};
  const retries={...field('retryLimit','重试上限','number',2),min:0,max:8};
  const reason=field('reason','原因','textarea');
  const experienceFields=[field('content','技能内容','textarea',t?.content),field('conditions','适用条件','textarea',t?.conditions),field('evidence','验证证据','textarea',t?.evidence)];
  let fields:Field[]=[];let note='保存到本机服务端，保留范围与修订记录。';let submit='保存';let make=(v:Record<string,unknown>)=>Object.fromEntries(Object.entries(v).filter(([k,value])=>k!=='scope'&&value!==''&&value!==undefined));
  const withId=(key:string)=>(v:Record<string,unknown>)=>({[key]:id,...Object.fromEntries(Object.entries(v).filter(([k,value])=>k!=='scope'&&value!==''&&value!==undefined))});
  switch(a){
    case 'inbox.capture': fields=[field('title','标题','text','',false),field('rawText','原始记录','textarea','',true,'保留原话，可稍后补充分类与批注。'),select('kind','记录类型',KINDS,'idea'),field('terminalId','来源终端','text','local'),select('projectId','关联项目',[['','暂不关联'],...projectOptions],'',false)];make=v=>({rawText:v.rawText,kind:v.kind,terminalId:v.terminalId,origin:'manual',...(v.title?{title:v.title}:{}),...(v.projectId?{projectId:v.projectId}:{})});submit='保存原话';break;
    case 'inbox.annotate':fields=[field('note','补充说明','textarea'),field('title','整理标题','text',t?.title,false),field('tags','标签 · 每行一个','lines','',false)];make=v=>({inboxId:id,note:v.note,...(v.title?{title:v.title}:{}),tags:lines(v.tags)});break;
    case 'inbox.merge':fields=[select('targetId','合并到',same('inbox')),reason];make=withId('sourceId');note='仅同范围合并，两个来源原文均保留。';break;
    case 'inbox.route':fields=[select('target','整理到',[['experience','经验技能'],['research','灵感研究']],'experience')];make=v=>({inboxId:id,target:v.target});note='保持原始范围。归档后可在目标领域继续验证或研究。';submit='确认归档';break;
    case 'inbox.ignore':fields=[reason];make=withId('inboxId');submit='确认忽略';break;
    case 'inbox.capture-policy':fields=[machine,select('projectId','关联项目',[['','暂不关联'],...projectOptions],'',false),{key:'fields',label:'允许采集的字段',type:'multi',value:['summary','error','lesson'],options:[['summary','项目摘要'],['error','问题错误'],['lesson','经验教训'],['skill','通用技能'],['artifact','产物记录']]},field('enabled','启用授权记录','check',true,false),field('consent','我明确同意这些字段的采集','check',false,true)];make=v=>({machineId:v.machineId,fields:v.fields,enabled:v.enabled,consent:v.consent,...(v.projectId?{projectId:v.projectId}:{})});note='这里只保存授权政策；后台设备采集器尚未接入。';break;
    case 'research.create':fields=[field('title','研究主题'),field('raw','最初的想法','textarea')];submit='保存研究';break;
    case 'research.discuss':fields=[field('text','讨论记录','textarea'),field('question','要解决的问题','textarea',t?.question,false),field('criteria','决策标准','textarea',t?.criteria,false),field('hypotheses','待验证假设 · 每行一个','lines','',false)];make=v=>({researchId:id,text:v.text,...(v.question?{question:v.question}:{}),...(v.criteria?{criteria:v.criteria}:{}),hypotheses:lines(v.hypotheses)});break;
    case 'research.pause':fields=[reason];make=withId('researchId');break;
    case 'research.evidence':fields=[select('kind','证据方向',[['support','支持'],['counter','反证'],['unknown','尚不确定']]),field('title','证据标题'),field('summary','内容摘要','textarea'),field('source','来源'),field('locator','可复查位置','text','',true,'网页链接、书籍页码、文件路径或具体记录。'),select('status','核实状态',[['unverified','尚未核实'],['verified','本人已核实'],['rejected','已否定']])];make=withId('researchId');submit='登记证据';break;
    case 'research.option':fields=[field('title','方案名称'),field('approach','实施方式','textarea'),field('risk','风险与限制','textarea'),field('effort','时间与工作量','text','',false),field('benefit','预期收益','textarea','',false),{...field('budget','预计费用 · 元','number',0,false),min:0},field('recommended','推荐此方案','check',false,false)];make=withId('researchId');break;
    case 'research.decide':fields=[select('choice','处理决定',[['accepted','采纳'],['deferred','暂缓'],['rejected','拒绝']]),select('optionId','采纳的方案',[['','不采纳时可留空'],...arr(t?.options).map(x=>[str(x.id),str(x.title)] as Option)],'',false),reason];make=withId('researchId');note='采纳需要已有证据与方案，服务端再次校验。';submit='确认决定';break;
    case 'research.convert':fields=[field('name','项目名称','text',t?.title),field('description','项目说明','textarea',t?.raw),field('goal','交付目标','textarea',t?.question),field('milestones','里程碑 · 每行一个','lines'),field('repo','仓库地址或路径','text','',false)];make=v=>({researchId:id,...makeBase(v),milestones:lines(v.milestones)});note='仅已采纳的研究可立项，原始范围保持不变。';submit='确认立项';break;
    case 'projects.register':fields=[field('name','项目名称'),field('description','项目说明','textarea'),field('goal','交付目标','textarea'),field('repo','仓库地址或路径','text','',false),field('milestones','里程碑 · 每行一个','lines','',false),field('copies','工作副本','copies',[],false)];make=v=>({...makeBase(v),milestones:lines(v.milestones),copies:v.copies});submit='登记项目';break;
    case 'projects.copies':fields=[field('copies','工作副本','copies',Array.isArray(t?.copies)?t.copies:[],false)];make=v=>({projectId:id,copies:v.copies});note='登记机器、路径和分支，不会自动访问或修改文件。';break;
    case 'projects.milestone':fields=[select('milestoneId','里程碑',arr(t?.milestones).map((x,i)=>[String(i),str(x.title)||str(x.name)||`里程碑 ${i+1}`])),field('completed','确认已完成','check',true,false),field('evidence','完成证据','textarea')];make=v=>({projectId:id,milestoneId:Number(v.milestoneId),completed:v.completed,evidence:v.evidence});break;
    case 'projects.plan':fields=[machine,field('agent','计划使用的开发工具','text','Codex'),budget,retries];make=withId('projectId');note='生成真实待执行任务，不会启动 AI 或远程机器。';submit='生成待执行计划';break;
    case 'projects.archive':fields=[reason];make=withId('projectId');note='关联的活动任务须先处理完成。';submit='确认归档';break;
    case 'tasks.create':fields=[field('title','任务名称'),select('projectId','所属项目',projectOptions),machine,field('agent','使用的开发工具','text','Codex'),select('mode','监督方式',[['managed','可管理的任务'],['observe','只观察登记']]),field('goal','要完成什么','textarea'),field('criteria','如何判断完成','textarea'),budget,retries,field('worktree','工作目录','text','',false),field('deadline','截止时间','datetime','',false)];make=v=>({...makeBase(v),...(v.deadline?{deadline:new Date(String(v.deadline)).toISOString()}:{} )});note='任务登记后等待外部执行。当前没有自动运行 Codex / Claude Code 的执行器。';submit='创建任务';break;
    case 'tasks.report':fields=[select('status','当前外部状态',[['running','外部进行中'],['paused','外部已暂停'],['validating','提交待验收'],['failed','外部失败']]),{...field('progress','进度 · %','number',t?.progress??0),min:0,max:100},field('source','报告来源','text','本人检查外部开发会话'),field('evidence','本次检查证据','textarea'),field('artifacts','产物路径或链接 · 每行一个','lines',Array.isArray(t?.artifacts)?t.artifacts.join('\n'):'',false)];make=v=>({taskId:id,status:v.status,progress:Number(v.progress),source:v.source,evidence:v.evidence,artifacts:lines(v.artifacts)});note='这是本人录入的外部进度，不代表贾维斯执行器已启动或已核实交付。';submit='提交外部报告';break;
    case 'tasks.pause':case 'tasks.cancel':fields=[reason];make=withId('taskId');note=command==='pause'?'记录暂停状态，不会停止尚未接入的外部进程。':'取消登记任务，不会替你结束外部开发会话。';submit=command==='pause'?'确认暂停':'确认取消';break;
    case 'tasks.accept':fields=[select('outcome','验收结论',[['pass','通过'],['fail','不通过']]),field('evidence','独立检查证据','textarea'),field('tests','实际完成的验证','textarea'),field('artifacts','验收产物 · 每行一个','lines',Array.isArray(t?.artifacts)?t.artifacts.join('\n'):'')];make=v=>({taskId:id,acceptance:{outcome:v.outcome,evidence:v.evidence,tests:v.tests,artifacts:lines(v.artifacts)}});note='只允许待验收任务。通过须填写实际产物与检查证据，AI 自报完成不算验收。';submit='提交验收';break;
    case 'tasks.package':fields=[field('version','交付版本','text','1.0.0'),field('criteria','交付说明','textarea','',false)];make=withId('taskId');note='仅已验收且有产物的任务可打包。服务端保留固定交付版本。';submit='打包交付';break;
    case 'experiences.capture':fields=[field('title','经验标题'),field('content','经验内容','textarea'),select('kind','内容类型',EXPERIENCE_KINDS),field('source','来源','text','本人开发记录'),field('conditions','适用条件','textarea','',false)];submit='保存经验';break;
    case 'experiences.verify':fields=[field('conditions','适用条件','textarea',t?.conditions),field('evidence','实际验证证据','textarea',t?.evidence)];make=withId('experienceId');note='填写实际验证过程和结果，整理文字本身不算验证。';submit='确认验证';break;
    case 'experiences.merge':fields=[select('baseId','合并到',same('experiences')),reason];make=withId('experienceId');note='只允许同范围经验，历史来源不会丢失。';break;
    case 'experiences.skill-publish':case 'experiences.version':fields=[field('version','内容版本','text',command==='version'?'':t?.version||'1.0.0'),...experienceFields];make=withId('experienceId');note=command==='version'?'生成修订版本后需要重新验证与发布，历史引用仍固定旧版。':'仅已验证经验可以发布，内容、适用条件及证据一并保存。';submit=command==='version'?'保存修订版本':'发布技能';break;
    case 'experiences.reuse':fields=[field('version','固定引用版本','text',t?.version),select('targetType','复用到',[['project','项目'],['task','任务']]),select('projectId','项目',[['','请选择'],...projectOptions],'',false),select('taskId','任务',[['','请选择'],...same('tasks')],'',false)];make=v=>({experienceId:id,version:v.version,...(v.targetType==='project'?{projectId:v.projectId}:{taskId:v.taskId})});note='固定已发布版本。请选择对应项目或任务，服务端检查权限与可用状态。';submit='确认复用';break;
    case 'experiences.deprecate':fields=[reason];make=withId('experienceId');note='保留历史引用，并停止新任务复用。';submit='确认停用';break;
  }
  return {title:COMMAND_LABELS[a]||DOMAINS.find(d=>d.id===domain)?.createLabel||'保存记录',note,submit,fields,make};
}
function makeBase(v:Record<string,unknown>){return Object.fromEntries(Object.entries(v).filter(([k,value])=>k!=='scope'&&k!=='milestones'&&value!==''&&value!==undefined));}

function CopyField({value,change,devices}:{value:unknown;change:(value:unknown)=>void;devices:Device[]}){
  const copies=arr(value);const update=(i:number,key:string,v:string)=>change(copies.map((x,n)=>i===n?{...x,[key]:v}:x));
  return <div className="v1-copies">{copies.map((copy,i)=><div className="v1-copy" key={i}><label>机器<select aria-label={`副本 ${i+1} 机器`} required value={str(copy.machineId)} onChange={e=>update(i,'machineId',e.target.value)}>{devices.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></label><label>工作路径<input aria-label={`副本 ${i+1} 工作路径`} required value={str(copy.path)} onChange={e=>update(i,'path',e.target.value)} placeholder="D:\\AI\\workspaces\\project"/></label><label>分支<input aria-label={`副本 ${i+1} 分支`} required value={str(copy.branch)} onChange={e=>update(i,'branch',e.target.value)}/></label><label>环境<select aria-label={`副本 ${i+1} 环境`} value={str(copy.environment)} onChange={e=>update(i,'environment',e.target.value)}>{ENVIRONMENTS.map(x=><option key={x[0]} value={x[0]}>{x[1]}</option>)}</select></label><button type="button" className="v1-text danger" onClick={()=>change(copies.filter((_,n)=>n!==i))}>移除此副本</button></div>)}<button type="button" className="v1-secondary" onClick={()=>change([...copies,{machineId:devices[0]?.id||'local',path:'',branch:'main',environment:'development'}])}>＋添加工作副本</button></div>;
}
function CommandForm({action,collections,devices,onSubmit,onClose,busy,error}:{action:Action;collections:Record<V1Domain,V1Collection>;devices:Device[];onSubmit:(payload:Record<string,unknown>,scope:V1Scope)=>void;onClose:()=>void;busy:boolean;error:string}){
  const initial=specFor(action,collections,devices,action.target?.scope||'personal');const [values,setValues]=useState<Record<string,unknown>>(()=>({...Object.fromEntries(initial.fields.map(f=>[f.key,f.value??''])),scope:action.target?.scope||'personal'}));
  const spec=specFor(action,collections,devices,values.scope as V1Scope);
  const change=(key:string,value:unknown)=>setValues(old=>{if(key==='scope'){const next=specFor(action,collections,devices,value as V1Scope);return {...old,scope:value,...Object.fromEntries(next.fields.filter(f=>['projectId','taskId','targetId','baseId'].includes(f.key)).map(f=>[f.key,f.options?.[0]?.[0]||''])),...(value==='company'&&action.domain==='tasks'?{mode:'observe'}:{})}}return {...old,[key]:value}});
  function submit(e:FormEvent){e.preventDefault();onSubmit(spec.make(values),values.scope as V1Scope)}
  return <Modal title={spec.title} subtitle={action.target?name(action.target):'真实数据录入'} onClose={()=>{if(!busy)onClose()}}><form onSubmit={submit} className="v1-form"><p className="v1-form-note"><Icon type="shield" small/>{spec.note}</p>{action.target?<div className="v1-version"><Badge>{scopeName(action.target.scope)}</Badge><span>基于修订 {action.target.revision} 提交</span></div>:<label>资料范围<select value={str(values.scope)} onChange={e=>change('scope',e.target.value)}>{SCOPES.map(x=><option value={x[0]} key={x[0]}>{x[1]}</option>)}</select></label>}{spec.fields.map(f=><div key={f.key} className={`v1-field ${f.type==='textarea'||f.type==='lines'||f.type==='copies'?'wide':''}`}>
    {f.type==='copies'?<><span className="v1-field-title">{f.label}</span><CopyField devices={devices} value={values[f.key]} change={v=>change(f.key,v)}/></>:f.type==='multi'?<fieldset className="v1-multi"><legend>{f.label}</legend>{f.options?.map(option=><label className="v1-check" key={option[0]}><input aria-label={option[1]} type="checkbox" checked={Array.isArray(values[f.key])&&(values[f.key] as string[]).includes(option[0])} onChange={e=>{const current=Array.isArray(values[f.key])?values[f.key] as string[]:[];change(f.key,e.target.checked?[...current,option[0]]:current.filter(x=>x!==option[0]))}}/>{option[1]}</label>)}</fieldset>:f.type==='check'?<label className="v1-check"><input aria-label={f.label} aria-required={f.required||undefined} type="checkbox" required={f.required} checked={!!values[f.key]} onChange={e=>change(f.key,e.target.checked)}/><span>{f.label}</span></label>:<label>{f.label}{f.required&&<span aria-hidden="true" className="v1-required"> *</span>}{f.type==='textarea'||f.type==='lines'?<textarea aria-label={f.label} aria-required={f.required||undefined} required={f.required} maxLength={f.type==='lines'?20000:20000} value={str(values[f.key])} onChange={e=>change(f.key,e.target.value)} rows={f.type==='lines'?3:4}/>:f.type==='select'?<select aria-label={f.label} aria-required={f.required||undefined} required={f.required} value={str(values[f.key])} onChange={e=>change(f.key,e.target.value)}>{f.options?.map(x=><option key={x[0]} value={x[0]}>{x[1]}</option>)}</select>:<input aria-label={f.label} aria-required={f.required||undefined} required={f.required} type={f.type==='number'?'number':f.type==='datetime'?'datetime-local':'text'} min={f.min} max={f.max} maxLength={4000} value={String(values[f.key]??'')} onChange={e=>change(f.key,f.type==='number'?(e.target.value===''?'':Number(e.target.value)):e.target.value)}/>}</label>}{f.hint&&<small>{f.hint}</small>}</div>)}{error&&<div className="v1-error wide" role="alert">{error}</div>}<footer><button type="button" className="v1-secondary" disabled={busy} onClick={onClose}>取消</button><button type="submit" className="v1-primary" disabled={busy}>{busy?'正在保存…':spec.submit}<Icon type="check" small/></button></footer></form></Modal>;
}

function AuthPanel({state,onSuccess}:{state:AuthState;onSuccess:()=>void}){
  const [password,setPassword]=useState('');const [confirm,setConfirm]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  async function submit(e:FormEvent){e.preventDefault();if(state.setupRequired&&password!==confirm){setError('两次密码不一致');return}setBusy(true);setError('');try{await v1Authenticate(state.setupRequired,password);setPassword('');setConfirm('');onSuccess()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  return <main className="v1-auth"><section className="v1-auth-art"><span className="v1-wordmark">JARVIS<span> / FOUNDATION</span></span><div className="v1-auth-orbit"><i/><i/><i/><b>J</b></div><div><span className="v1-eyebrow">FROM IDEAS TO DELIVERY</span><h1>你的每件事，<br/>都有真实着落。</h1><p>收件 · 研究 · 项目 · 任务 · 经验</p></div><Links/></section><section className="v1-auth-card"><Badge tone="green">真实数据工作台</Badge><h2>{state.setupRequired?'建立管理账户':'欢迎回来'}</h2><p>{state.setupRequired?'设置本机管理密码，开始保存你的数据。':'使用已有管理密码登录，继续处理你的事项。'}</p><form onSubmit={submit}><label>管理密码<input autoFocus type="password" autoComplete={state.setupRequired?'new-password':'current-password'} minLength={state.setupRequired?12:1} maxLength={256} required value={password} onChange={e=>setPassword(e.target.value)} placeholder={state.setupRequired?'至少 12 个字符':'输入管理密码'}/></label>{state.setupRequired&&<label>确认密码<input type="password" autoComplete="new-password" minLength={12} maxLength={256} required value={confirm} onChange={e=>setConfirm(e.target.value)}/></label>}{error&&<p className="v1-error" role="alert">{error}</p>}<button className="v1-primary" type="submit" disabled={busy}>{busy?'正在连接…':state.setupRequired?'创建账户':'进入工作台'}<Icon type="arrow" small/></button></form><small><Icon type="shield" small/>当前仅管理员本机使用 · 家庭身份认证尚未接入</small></section></main>;
}

function RecordDetail({domain,record,collections,devices,events,releases,action,capabilities,locked}:{domain:V1Domain;record:V1Record;collections:Record<V1Domain,V1Collection>;devices:Device[];events:V1Event[];releases:V1Record[];action:(command:string)=>void;capabilities:V1Capabilities|null;locked:boolean}) {
  const available=capabilities?.domains.find(d=>d.domain===domain);const labels=DOMAINS.find(d=>d.id===domain)!;
  const commands=(available?.commands||[]).filter(c=>c!==labels.create&&c!=='capture-policy'&&!available?.unavailableCommands.includes(c));
  const disabled=(c:string)=>domain==='tasks'?((c==='accept'&&record.status!=='validating')||(c==='package'&&record.status!=='completed')||(c==='report'&&['completed','cancelled','failed'].includes(record.status))||(['pause','cancel'].includes(c)&&(record.mode==='observe'||['completed','cancelled'].includes(record.status)))):domain==='inbox'?(['route','ignore','merge','annotate'].includes(c)&&record.status!=='pending'):domain==='research'?(c==='convert'&&record.status!=='accepted')||record.status==='converted':domain==='experiences'?(c==='skill-publish'&&(!record.verified||record.status!=='verified'||!!record.publishedSkillId))||(['version','reuse','deprecate'].includes(c)&&record.kind!=='skill')||(c==='version'&&!['published','deprecated'].includes(record.status))||(c==='reuse'&&record.status!=='published')||(c==='deprecate'&&record.status!=='published'):false;
  const project=collections.projects.items.find(p=>p.id===record.projectId);
  const lastReport=arr(record.externalReports).at(-1);
  if(lastReport)record={...record,reportSource:str(lastReport.source)};
  return <article className="v1-detail" aria-label="记录详情"><header className="v1-detail-heading"><div><div className="v1-detail-badges"><Badge tone={['completed','published','verified','accepted'].includes(record.status)?'green':''}>{STATUS[record.status]||record.status}</Badge><Badge>{scopeName(record.scope)}</Badge><span>修订 {record.revision}</span></div><h2>{name(record)}</h2><small>{record.id}</small></div><Icon type={domain}/></header>
    <div className="v1-actions" aria-label="详情操作">{commands.map(c=><button className={c==='accept'||c==='route'||c==='verify'?'v1-primary':'v1-secondary'} key={c} disabled={locked||disabled(c)} onClick={()=>action(c)}>{COMMAND_LABELS[`${domain}.${c}`]||c}</button>)}</div>
    {domain==='inbox'&&<><Block label="原始记录"><Text value={record.rawText}/></Block><div className="v1-facts"><div><span>类型</span><strong>{KINDS.find(x=>x[0]===record.kind)?.[1]||str(record.kind)}</strong></div><div><span>来源终端</span><strong>{str(record.terminalId)}</strong></div><div><span>采集方式</span><strong>{record.origin==='manual'?'人工录入':record.origin==='voice'?'语音':'设备提交'}</strong></div><div><span>记录时间</span><strong>{date(record.createdAt)}</strong></div></div>{arr(record.annotations).length>0&&<Block label="整理批注">{arr(record.annotations).map((x,i)=><div className="v1-evidence" key={i}><Text value={x.note}/><small>{date(x.at||x.createdAt)}</small></div>)}</Block>}{record.target&&typeof record.target==='object'&&<Block label="归档去向"><p>{['experience','experiences'].includes(str((record.target as Record<string,unknown>).domain||(record.target as Record<string,unknown>).type))?'经验技能':'灵感研究'} · {str((record.target as Record<string,unknown>).id)}</p></Block>}</>}
    {domain==='research'&&<><Block label="最初的想法"><Text value={record.raw}/></Block>{!!record.question&&<Block label="研究问题"><Text value={record.question}/></Block>}{!!record.criteria&&<Block label="决策标准"><Text value={record.criteria}/></Block>}<Block label={`证据 · ${arr(record.evidence).length}`}>{arr(record.evidence).length?arr(record.evidence).map((e,i)=><div className="v1-evidence" key={i}><Badge>{e.kind==='support'?'支持':e.kind==='counter'?'反证':'未知'}</Badge><Badge tone={e.status==='verified'?'green':''}>{e.status==='verified'?'已核实':e.status==='rejected'?'已否定':'待核实'}</Badge><h4>{str(e.title)}</h4><Text value={e.summary}/><small>{str(e.source)} · {str(e.locator)}</small></div>):<p className="v1-muted">尚无证据。可以先登记支持、反证或未知信息。</p>}</Block><Block label={`备选方案 · ${arr(record.options).length}`}>{arr(record.options).map((o,i)=><div className="v1-evidence" key={i}><h4>{str(o.title)} {!!o.recommended&&<Badge tone="green">推荐</Badge>}</h4><Text value={o.approach}/><small>风险：{str(o.risk)}</small></div>)}{!arr(record.options).length&&<p className="v1-muted">先讨论问题，再添加可比较的方案。</p>}</Block><p className="v1-truth-note">当前支持人工研究记录；后台 AI 研究未接入。</p></>}
    {domain==='projects'&&<><Block label="项目说明"><Text value={record.description}/></Block><Block label="交付目标"><Text value={record.goal}/></Block>{!!record.repo&&<Block label="仓库"><Text value={record.repo}/></Block>}<Block label={`工作副本 · ${arr(record.copies).length}`}>{arr(record.copies).map((c,i)=><div className="v1-copy-summary" key={i}><Icon type="projects" small/><div><strong>{devices.find(d=>d.id===c.machineId)?.name||str(c.machineId)}</strong><p>{str(c.path)}</p><small>{str(c.branch)} · {ENVIRONMENTS.find(e=>e[0]===c.environment)?.[1]||str(c.environment)}</small></div></div>)}{!arr(record.copies).length&&<p className="v1-muted">尚未登记工作副本。</p>}</Block><Block label="里程碑">{arr(record.milestones).map((m,i)=><div className="v1-milestone" key={i}><span className={m.completed?'done':''}>{m.completed?'✓':i+1}</span><div><strong>{str(m.title)||str(m.name)||`里程碑 ${i+1}`}</strong>{!!m.evidence&&<small>{str(m.evidence)}</small>}</div></div>)}{!arr(record.milestones).length&&<p className="v1-muted">尚无里程碑。</p>}</Block></>}
    {domain==='tasks'&&<><div className="v1-task-progress"><div><span>本人录入的外部进度</span><strong>{Number(record.progress)||0}<small>%</small></strong></div><div className="v1-progress"><i style={{width:`${Math.max(0,Math.min(100,Number(record.progress)||0))}%`}}/></div><small>{str(record.reportSource)||str(record.source)||'尚无外部报告'} · {date(record.updatedAt)}</small></div><div className="v1-facts"><div><span>项目</span><strong>{project?name(project):str(record.projectId)}</strong></div><div><span>开发设备</span><strong>{devices.find(d=>d.id===record.machineId)?.name||str(record.machineId)}</strong></div><div><span>开发工具</span><strong>{str(record.agent)}</strong></div><div><span>监督方式</span><strong>{record.mode==='observe'?'只观察':'任务登记'}</strong></div></div><Block label="交付目标"><Text value={record.goal}/></Block><Block label="验收标准"><Text value={record.criteria}/></Block>{!!record.worktree&&<Block label="工作目录"><Text value={record.worktree}/></Block>}<Block label="交付产物">{Array.isArray(record.artifacts)&&record.artifacts.length?<ul className="v1-artifact-list">{record.artifacts.map((x,i)=><li key={i}><Icon type="link" small/>{String(x)}</li>)}</ul>:<p className="v1-muted">尚无产物，提交待验收时需登记。</p>}</Block>{record.acceptance&&typeof record.acceptance==='object'&&<Block label="独立验收"><Badge tone={(record.acceptance as Record<string,unknown>).outcome==='pass'?'green':'orange'}>{(record.acceptance as Record<string,unknown>).outcome==='pass'?'已通过':'未通过'}</Badge><Text value={(record.acceptance as Record<string,unknown>).evidence}/><p className="v1-prose">验证：{str((record.acceptance as Record<string,unknown>).tests)}</p></Block>}<p className="v1-truth-note">未接入执行器。记录、暂停与验收均不会操作外部开发进程。</p></>}
    {domain==='experiences'&&<><div className="v1-facts"><div><span>内容类型</span><strong>{EXPERIENCE_KINDS.find(x=>x[0]===record.kind)?.[1]||str(record.kind)}</strong></div><div><span>内容版本</span><strong>{str(record.version)}</strong></div><div><span>验证</span><strong>{record.verified?'已验证':'尚未验证'}</strong></div><div><span>来源</span><strong>{str(record.source)}</strong></div></div><Block label="经验内容"><Text value={record.content}/></Block><Block label="适用条件"><Text value={record.conditions}/></Block><Block label="验证证据"><Text value={record.evidence}/></Block>{arr(record.history).length>0&&<Block label="历史版本">{arr(record.history).map((h,i)=><div className="v1-evidence" key={i}><strong>{str(h.version)||`版本 ${i+1}`}</strong><small>{date(h.at||h.createdAt)}</small>{!!h.content&&<Text value={h.content}/>}</div>)}</Block>}</>}
    {domain==='inbox'&&!!record.annotation&&<Block label="整理批注"><Text value={record.annotation}/></Block>}
    {domain==='research'&&arr(record.discussions).length>0&&<Block label="讨论记录">{arr(record.discussions).map((discussion,i)=><div className="v1-evidence" key={i}><Text value={discussion.text}/><small>{date(discussion.at)}</small></div>)}</Block>}
    {domain==='tasks'&&arr(record.externalReports).length>0&&<Block label={`外部人工报告 · ${arr(record.externalReports).length}`}><p className="v1-muted">最新来源：{str(lastReport?.source)}。报告内容由本人登记，尚未经平台执行器核实。</p>{[...arr(record.externalReports)].reverse().map((report,i)=><div className="v1-evidence" key={i}><Badge>{STATUS[str(report.status)]||str(report.status)}</Badge><Badge>{Number(report.progress)}%</Badge><h4>{str(report.source)}</h4><Text value={report.evidence}/><small>{date(report.at)} · {report.verification==='unverified_external'?'外部声明，尚未自动核实':str(report.verification)}</small>{Array.isArray(report.artifacts)&&report.artifacts.length>0&&<ul className="v1-artifact-list">{report.artifacts.map((artifact,n)=><li key={n}><Icon type="link" small/>{String(artifact)}</li>)}</ul>}</div>)}</Block>}
    {domain==='tasks'&&releases.filter(r=>r.taskId===record.id).length>0&&<Block label="固定交付版本">{releases.filter(r=>r.taskId===record.id).map(release=><div className="v1-release" key={release.id}><div><Badge tone="green">交付版本 {str(release.version)}</Badge><small>{date(release.createdAt)}</small></div><p>已固定产物与验收记录 · 尚未执行部署</p><ul className="v1-artifact-list">{Array.isArray(release.artifactIds)&&release.artifactIds.map((artifact,i)=><li key={i}><Icon type="link" small/>{String(artifact)}</li>)}</ul><small>{release.id}</small></div>)}</Block>}
    <Block label="修订事件">{events.length?<ol className="v1-event-list">{events.map(e=><li key={e.id}><i/><div><strong>{eventName(e.type)}</strong><small>#{e.sequence} · {date(e.at)}</small>{eventSummary(e.payload)&&<p>{eventSummary(e.payload)}</p>}</div></li>)}</ol>:<p className="v1-muted">尚未读取到此记录的修订事件。</p>}</Block>
  </article>;
}
function eventName(type:string){const labels:Record<string,string>={captured:'原话已保存',routed:'记录已归档',annotated:'批注已保存',merged:'记录已合并',ignored:'记录已忽略',created:'已创建',registered:'项目已登记',discussed:'讨论已补充',verified:'经验已验证',published:'技能已发布',version:'内容已修订',referenced:'固定版本已复用',deprecated:'经验已停用',reported:'外部进度已录入',external_reported:'外部人工进度已录入',acceptance_recorded:'独立验收已记录',accepted:'验收已记录',packaged:'交付已打包',paused:'已暂停',cancelled:'已取消',planned:'任务计划已生成',decided:'决策已保存',converted:'研究已立项',evidence:'证据已登记',option:'方案已添加'};const tail=type.split(/[.:]/).at(-1)||type;return labels[tail]||COMMAND_LABELS[type]||type;}
function eventSummary(payload:Record<string,unknown>){return ['summary','reason','source','outcome','status','version','evidence'].map(key=>payload[key]?`${({reason:'原因',source:'来源',outcome:'结论',status:'状态',version:'版本',evidence:'证据',summary:'摘要'} as Record<string,string>)[key]}：${STATUS[str(payload[key])]||str(payload[key])}`:'').filter(Boolean).join(' · ').slice(0,300)}

export default function ApiWorkbench(){
  const [auth,setAuth]=useState<AuthState|null>(null);const [connectionError,setConnectionError]=useState('');const [domain,setDomain]=useState<V1Domain>('inbox');const [collections,setCollections]=useState(EMPTY);const [capabilities,setCapabilities]=useState<V1Capabilities|null>(null);const [devices,setDevices]=useState<Device[]>([]);const [releases,setReleases]=useState<V1Record[]>([]);const [errors,setErrors]=useState<Partial<Record<V1Domain,string>>>({});const [loading,setLoading]=useState(false);const [detailBusy,setDetailBusy]=useState(false);const [selected,setSelected]=useState<V1Record|null>(null);const [events,setEvents]=useState<V1Event[]>([]);const [search,setSearch]=useState('');const [scopeFilter,setScopeFilter]=useState('');const [action,setAction]=useState<Action|null>(null);const [busy,setBusy]=useState(false);const [opening,setOpening]=useState(false);const [formError,setFormError]=useState('');const [notice,setNotice]=useState('');const [showCapabilities,setShowCapabilities]=useState(false);const pending=useRef<{key:string;id:string;version:number}|null>(null);const readSequence=useRef(0);const lifecycle=useRef(0);
  const expire=useCallback(()=>{lifecycle.current++;readSequence.current++;setAuth({setupRequired:false,authenticated:false});setCollections(EMPTY());setSelected(null);setEvents([]);setCapabilities(null);setDevices([]);setAction(null);setNotice('登录已过期，请重新登录。');},[]);
  const fail=useCallback((e:unknown)=>{if(e instanceof V1Error&&e.status===401){expire();return true}return false;},[expire]);
  const mergeEvents=useCallback((more:V1Event[])=>setEvents(old=>Array.from(new Map([...old,...more].map(e=>[e.id,e])).values()).sort((a,b)=>b.sequence-a.sequence)),[]);
  const refresh=useCallback(async()=>{const epoch=lifecycle.current;setLoading(true);const results=await Promise.allSettled([v1Capabilities(),v1Devices(),...DOMAINS.map(d=>v1List(d.id)),v1All('releases')]);if(epoch!==lifecycle.current)return;let expired=false;for(const result of results){if(result.status==='rejected'&&result.reason instanceof V1Error&&result.reason.status===401){expired=true;break}}if(expired){expire();setLoading(false);return}const caps=results[0];if(caps.status==='fulfilled'){setCapabilities((caps.value as Awaited<ReturnType<typeof v1Capabilities>>).data);setConnectionError('')}else setConnectionError(caps.reason.message||'能力状态读取失败');const ds=results[1];if(ds.status==='fulfilled')setDevices(ds.value as Device[]);const releaseResult=results[7];if(releaseResult.status==='fulfilled')setReleases((releaseResult.value as V1Collection).items);const nextErrors:Partial<Record<V1Domain,string>>={};const next:Partial<Record<V1Domain,V1Collection>>={};DOMAINS.forEach((d,i)=>{const result=results[i+2];if(result.status==='fulfilled'){const envelope=result.value as Awaited<ReturnType<typeof v1List>>;next[d.id]=envelope.data;mergeEvents(envelope.events||[])}else nextErrors[d.id]=result.reason.message||'读取失败'});setCollections(old=>({...old,...next}));setErrors(nextErrors);setLoading(false);},[expire,mergeEvents]);
  const checkAuth=useCallback(async()=>{setConnectionError('');try{const state=await v1AuthState();setAuth(state)}catch(e){setConnectionError((e as Error).message)}},[]);
  useEffect(()=>{void checkAuth()},[checkAuth]);useEffect(()=>{if(auth?.authenticated)void refresh()},[auth?.authenticated,refresh]);
  useEffect(()=>{if(!notice||busy)return;const timeout=window.setTimeout(()=>setNotice(''),6500);return()=>window.clearTimeout(timeout)},[notice,busy]);
  async function choose(record:V1Record){const sequence=++readSequence.current;setSelected(record);setDetailBusy(true);const results=await Promise.allSettled([v1Read(domain,record.id),v1AllHistory(domain,record.id)]);if(sequence!==readSequence.current)return;for(const result of results)if(result.status==='rejected'&&fail(result.reason)){setDetailBusy(false);return}const result=results[0];if(result.status==='fulfilled')setSelected((result.value as Awaited<ReturnType<typeof v1Read>>).data);else setNotice(result.reason.message);const history=results[1];if(history.status==='fulfilled')mergeEvents(history.value as V1Event[]);else setNotice(`修订事件读取未完成：${history.reason.message}`);setDetailBusy(false)}
  function navigate(next:V1Domain){if(busy||opening)return;readSequence.current++;setDomain(next);setSelected(null);setSearch('');setScopeFilter('');setDetailBusy(false)}
  async function open(command:string,target?:V1Record){if(opening||busy)return;const sequence=readSequence.current;const epoch=lifecycle.current;setOpening(true);try{const related:V1Domain[]=command==='merge'?[domain]:domain==='tasks'||command==='capture'||command==='capture-policy'||command==='reuse'?command==='reuse'?['projects','tasks']:['projects']:[];const results=await Promise.all(related.map(async d=>[d,await v1All(d)] as const));if(epoch!==lifecycle.current||sequence!==readSequence.current)return;setCollections(old=>({...old,...Object.fromEntries(results)}));setAction({domain,command,target});setFormError('');pending.current=null}catch(e){if(!fail(e))setNotice(`关联数据读取未完成：${(e as Error).message}`)}finally{setOpening(false)}}
  async function submit(payload:Record<string,unknown>,scope:V1Scope){if(!action||busy)return;setBusy(true);setFormError('');const epoch=lifecycle.current;const savedAction=action;let expectedVersion=action.target?.revision??0;
    try{const key=JSON.stringify([savedAction.domain,savedAction.command,payload,scope,expectedVersion]);if(pending.current?.key===key)expectedVersion=pending.current.version;else{if(savedAction.command==='capture-policy'){const policies=await v1All('capture-policies');const existing=policies.items.find(p=>p.scope===scope&&p.machineId===payload.machineId&&(p.projectId??null)===(payload.projectId??null));expectedVersion=existing?.revision??0}pending.current={key,id:crypto.randomUUID(),version:expectedVersion}}const result=await v1Command(savedAction.domain,savedAction.command,payload,scope,expectedVersion,pending.current.id);if(epoch!==lifecycle.current)return;mergeEvents(result.events||[]);setAction(null);pending.current=null;setNotice(`${specFor(savedAction,collections,devices).submit}已完成 · 服务修订 ${result.version}`);await refresh();const resultDomain:V1Domain=savedAction.domain==='research'&&savedAction.command==='convert'?'projects':savedAction.domain;const currentId=result.data?.id;if(currentId&&savedAction.command!=='capture-policy'){if(resultDomain!==savedAction.domain){readSequence.current++;setDomain(resultDomain);setSelected(null);setSearch('');setScopeFilter('')}const [detail,history]=await Promise.all([v1Read(resultDomain,currentId),v1AllHistory(resultDomain,currentId)]);if(epoch===lifecycle.current){setSelected(detail.data);mergeEvents(history)}}}
    catch(e){if(!fail(e)){setFormError((e as Error).message);if(e instanceof V1Error&&e.status===409){await refresh();if(savedAction.target){try{const fresh=await v1Read(savedAction.domain,savedAction.target.id);setSelected(fresh.data);mergeEvents(fresh.events||[]);if(fresh.data.revision!==savedAction.target.revision){setAction(old=>old?{...old,target:fresh.data}:old);pending.current=null;setFormError('这条记录已发生修订，已载入最新版本。请复核内容后再次提交。')}}catch{setFormError('记录刷新未完成。请关闭表单、重新读取详情后重试。')}}else if(savedAction.command==='capture-policy'){pending.current=null;setFormError('授权记录已修订。请复核选择后再次提交。')}}}}
    finally{setBusy(false)}
  }
  async function loadMore(){const cursor=collections[domain].nextCursor;if(!cursor||loading)return;setLoading(true);try{const response=await v1List(domain,cursor);setCollections(old=>({...old,[domain]:{...response.data,items:Array.from(new Map([...old[domain].items,...response.data.items].map(x=>[x.id,x])).values())}}));mergeEvents(response.events||[])}catch(e){if(!fail(e))setNotice((e as Error).message)}finally{setLoading(false)}}
  async function logout(){if(busy)return;try{await v1Logout();expire();setNotice('已退出管理账户。')}catch(e){setNotice((e as Error).message)}}
  const current=DOMAINS.find(d=>d.id===domain)!;const items=collections[domain].items.filter(x=>(!scopeFilter||x.scope===scopeFilter)&&(!search||[name(x),str(x.content),str(x.rawText),str(x.raw),str(x.description)].join(' ').toLowerCase().includes(search.toLowerCase())));const capability=capabilities?.domains.find(d=>d.domain===domain);const canCreate=capability?.commands.includes(current.create)&&!capability.unavailableCommands.includes(current.create);const currentEvents=events.filter(e=>selected&&e.domain===domain&&e.objectId===selected.id);
  if(!auth)return <div className="v1-workbench"><div className="v1-connecting"><span className="v1-wordmark">JARVIS / FOUNDATION</span><h1>{connectionError?'本机服务尚未连接':'正在连接你的工作台…'}</h1>{connectionError&&<><p className="v1-error">{connectionError}</p><button className="v1-primary" onClick={()=>void checkAuth()}>重试连接</button></>}<Links/></div></div>;
  if(!auth.authenticated)return <div className="v1-workbench"><AuthPanel state={auth} onSuccess={()=>void checkAuth()}/></div>;
  return <div className="v1-workbench"><aside className="v1-sidebar"><a className="v1-brand" href="?mode=api"><span>J</span><div><strong>贾维斯</strong><small>真实数据工作台</small></div></a><div className="v1-server"><i/>本机服务 · 已登录</div><nav aria-label="工作台领域">{DOMAINS.map(d=><button className={domain===d.id?'active':''} key={d.id} onClick={()=>navigate(d.id)}><Icon type={d.id}/><span>{d.label}</span><b>{collections[d.id].items.length}{collections[d.id].nextCursor?'+':''}</b></button>)}</nav><div className="v1-sidebar-bottom"><button className="v1-secondary" onClick={()=>setShowCapabilities(true)}><Icon type="shield" small/>能力接入状态</button><Links/><button className="v1-text" onClick={()=>void logout()}><Icon type="logout" small/>退出登录</button></div></aside><div className="v1-content"><header className="v1-topbar"><div><Badge tone="green">真实数据</Badge><span>服务端持久化 · 独立于交互演示</span></div><button className="v1-text" disabled={loading} onClick={()=>void refresh()}><Icon type="refresh" small/>{loading?'读取中…':'刷新数据'}</button></header><main><div className="v1-page-heading"><div><span className="v1-eyebrow">{current.english} / FOUNDATION</span><h1>{current.label}</h1><p>{current.detail}</p></div><div className="v1-heading-actions">{domain==='inbox'&&capability?.commands.includes('capture-policy')&&<button className="v1-secondary" onClick={()=>open('capture-policy')}>采集授权</button>}<button className="v1-primary" disabled={!canCreate||loading} onClick={()=>open(current.create)}><Icon type="plus" small/>{current.createLabel}</button></div></div>
    <section className="v1-flow-strip" aria-label="真实业务闭环">{[['inbox','记录原话'],['research','研究决策'],['projects','登记项目'],['tasks','验证交付'],['experiences','沉淀经验']].map(([d,label],i)=><button key={d} onClick={()=>navigate(d as V1Domain)} className={d===domain?'active':''}><i>{i+1}</i><span>{label}</span><Icon type="arrow" small/></button>)}</section>
    {connectionError&&<div className="v1-error" role="alert">{connectionError}<button className="v1-text" onClick={()=>void refresh()}>重试</button></div>}
    <div className="v1-data-layout"><section className="v1-records"><header><div className="v1-search"><Icon type="search" small/><input aria-label="搜索当前列表" placeholder="搜索标题或内容" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="筛选资料范围" value={scopeFilter} onChange={e=>setScopeFilter(e.target.value)}><option value="">全部范围</option>{SCOPES.map(x=><option key={x[0]} value={x[0]}>{x[1]}</option>)}</select></header><div className="v1-list-meta"><span>{items.length} 条{search||scopeFilter?'匹配记录':'记录'}</span><span>快照 {collections[domain].snapshotVersion}</span></div>{errors[domain]?<div className="v1-empty"><Icon type="shield"/><h2>数据读取未完成</h2><p>{errors[domain]}</p><button className="v1-secondary" onClick={()=>void refresh()}>重新读取</button></div>:items.length?<div className="v1-list">{items.map(item=><button className={`v1-record ${selected?.id===item.id?'selected':''}`} key={item.id} onClick={()=>void choose(item)}><div><h3>{name(item)}</h3><Badge tone={['completed','published','verified','accepted'].includes(item.status)?'green':''}>{STATUS[item.status]||item.status}</Badge></div><p>{str(item.rawText)||str(item.raw)||str(item.content)||str(item.description)||str(item.goal)}</p><footer><span>{scopeName(item.scope)} · r{item.revision}</span>{domain==='tasks'?<span>{Number(item.progress)||0}% · 人工报告</span>:<span>{date(item.updatedAt||item.createdAt)}</span>}</footer></button>)}</div>:<div className="v1-empty"><Icon type={domain}/><h2>{loading?'正在读取真实数据…':search||scopeFilter?'没有匹配的记录':'从第一条真实记录开始'}</h2><p>{loading?'请稍候。':search||scopeFilter?'调整筛选条件后再试。':current.detail}</p>{!loading&&!search&&!scopeFilter&&<button className="v1-primary" disabled={!canCreate} onClick={()=>open(current.create)}>{current.createLabel}<Icon type="plus" small/></button>}</div>}{collections[domain].nextCursor&&<button className="v1-load-more" disabled={loading} onClick={()=>void loadMore()}>{loading?'读取中…':'加载更多真实记录'}</button>}</section>
    <section className="v1-detail-pane">{selected?<><div className="v1-detail-top"><span>{detailBusy?'读取最新修订…':'详情与操作'}</span><button className="v1-text" onClick={()=>{readSequence.current++;setSelected(null);setDetailBusy(false)}}>收起详情</button></div><RecordDetail domain={domain} record={selected} collections={collections} devices={devices} events={currentEvents} releases={releases} capabilities={capabilities} locked={busy||opening||detailBusy} action={command=>void open(command,selected)}/></>:<div className="v1-detail-intro"><div className="v1-intro-icon"><Icon type={domain}/></div><span className="v1-eyebrow">A TRACEABLE WORKFLOW</span><h2>每一步，都可追溯。</h2><p>选择一条记录，查看原文、范围、修订与下一步操作。</p><div className="v1-intro-boundaries"><strong>当前可以</strong><span>真实录入、整理与归档</span><span>记录人工进度与检查证据</span><span>独立验收、固定版本交付</span><strong>等待接入</strong><span>自动研发执行器 · 后台研究</span><span>房间语音 · 书籍 OCR · 远程代理</span></div><button className="v1-text" onClick={()=>setShowCapabilities(true)}>查看接入状态<Icon type="arrow" small/></button></div>}</section></div>
    <footer className="v1-page-footer"><Icon type="shield" small/><span>管理员会话由服务器验证。资料范围不会因整理归档自动扩大。</span><span>本机基础版</span></footer></main></div>
    {notice&&<div className="v1-toast" role="status" aria-live="polite"><span>{notice}</span></div>}
    {action&&<CommandForm key={`${action.domain}.${action.command}.${action.target?.id||'new'}`} action={action} collections={collections} devices={devices} onSubmit={(p,s)=>void submit(p,s)} busy={busy} error={formError} onClose={()=>setAction(null)}/>}
    {showCapabilities&&<Modal title="能力接入状态" subtitle="以当前服务返回为准" onClose={()=>setShowCapabilities(false)}><div className="v1-capabilities"><p className="v1-form-note"><Icon type="shield" small/>目前只认证本机管理员。家庭成员独立身份还未接入。</p>{capabilities?.domains.map(d=><div className="v1-capability" key={d.domain}><div><strong>{DOMAINS.find(x=>x.id===d.domain)?.label||d.domain}</strong><Badge tone={d.status==='ready'?'green':d.status==='partial'?'orange':''}>{STATUS[d.status]||d.status}</Badge></div><p>{d.description}</p><small>{d.commands.filter(c=>!d.unavailableCommands.includes(c)).length} 个可用命令{d.unavailableCommands.length?` · ${d.unavailableCommands.length} 个命令等待接入`:''}</small></div>)}<h3>外部能力</h3>{[['development','自动研发执行器'],['backgroundResearch','后台 AI 研究'],['remoteAgents','远程设备代理'],['voice','房间语音'],['ocr','扫描书籍 OCR'],['piConfigured','Pi 对话模型配置']].map(([key,label])=><div className="v1-capability-line" key={key}><span>{label}</span><Badge tone={capabilities?.execution[key as keyof V1Capabilities['execution']]?'green':''}>{capabilities?.execution[key as keyof V1Capabilities['execution']]?key==='piConfigured'?'已配置，健康需实际验证':'已接入':'尚未接入'}</Badge></div>)}<a className="v1-secondary" href="?mode=live#settings">在真实控制台配置 Pi <Icon type="arrow" small/></a></div></Modal>}
  </div>;
}
